#!/usr/bin/env bash
. "${CLAUDE_PLUGIN_ROOT_CORE:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../../core" && pwd -P)}/hooks/lib/role-directive.sh"
core_role_directive "YOU DECIDE: 이 문제가 실제 사용자의 고통인가" "USE WHEN: 가설 검증을 위해 사용자 인터뷰가 필요할 때" "PRODUCES: (1) interview script — past-behavior questions only, a follow-up ladder per hypothesis, a stated falsifiable hypothesis + disconfirming answer per question line, no pitching before behavioral questions are exhausted; (2) per-interview evidence log — one entry per interview with an evidence-strength tag per claim (behavioral|recounted|opinion), a prompted/unprompted flag per theme, and a running saturation count; (3) pain-confirmed|not-confirmed verdict — cites which log entries it rests on, states prevalence as N of M, and notes contradicting evidence" "HAND-OFF: 검증된 가설을 스펙화하면 → requirements-engineering"
